-- Replaces the contents of quiz_examples with the 57 questions in src/data/quizBank.json.
-- Paste into the Supabase SQL editor and run. Safe to re-run: it clears the table first.
delete from quiz_examples;
insert into quiz_examples (channel,sender,subject,body,link_text,link_url,is_phishing,category,difficulty,clues,explanation,source,source_url) select channel,sender,subject,body,link_text,link_url,is_phishing,category,difficulty,clues,explanation,source,source_url from jsonb_to_recordset($q$[{"channel":"email","sender":"IRD Refunds <refunds@ird-govt-nz.com>","subject":"Your tax summary is available","body":"Kia ora,\n\nYour 2026 tax summary is ready to view. A refund of $412.60 is waiting for you.\n\nConfirm your details to receive your payment.","link_text":"View my tax summary","link_url":"https://ird-govt-nz.com/myir/summary","is_phishing":true,"category":"Tax and government","difficulty":"easy","clues":["The sender domain is ird-govt-nz.com. Inland Revenue emails come from ird.govt.nz.","Inland Revenue does not put links in its emails.","A refund that is just waiting for you is bait."],"explanation":"This copies the 'your tax summary is available' scam Inland Revenue has warned about. The domain only looks like the real one because the dots were swapped for hyphens.","source":"Modelled on Inland Revenue's latest scams page","source_url":"https://www.ird.govt.nz/managing-my-tax/scams/latest-scams"},{"channel":"email","sender":"Inland Revenue <noreply@myir-refunds.net>","subject":"We could not pay your refund","body":"Your refund could not be paid because your bank account details are missing.\n\nAdd them within 5 working days or the refund will be returned to Inland Revenue.","link_text":"Add bank details","link_url":"https://myir-refunds.net/add-account","is_phishing":true,"category":"Tax and government","difficulty":"medium","clues":["The address is not @ird.govt.nz.","It asks for bank details through a link.","A short deadline is there to rush you."],"explanation":"The 'missing bank details' message is one of the refund lures Inland Revenue lists. Real refunds are managed after you log in to myIR yourself, not through an emailed link.","source":"Modelled on Inland Revenue's latest scams page","source_url":"https://www.ird.govt.nz/managing-my-tax/scams/latest-scams"},{"channel":"sms","sender":"+64 21 555 0143","subject":"","body":"MyIR Team: You have 1 new message from Inland Revenue. Read it here before it is archived.","link_text":"Read message","link_url":"https://myir-secure.top/msg","is_phishing":true,"category":"Tax and government","difficulty":"medium","clues":["It came from an ordinary mobile number. Inland Revenue texts from 5678 or 4478.","Inland Revenue does not include links in texts.","The link ends in .top, a cheap ending that scammers use a lot."],"explanation":"Inland Revenue has said it texts only from the short numbers 5678 and 4478, never includes links, and does not use the name 'MyIR Team'. This message breaks all three rules.","source":"Modelled on Inland Revenue's latest scams page","source_url":"https://www.ird.govt.nz/managing-my-tax/scams/latest-scams"},{"channel":"email","sender":"Compliance Unit <legal@inlandrevenue-nz.org>","subject":"Final notice: unpaid tax","body":"Our records show you owe $1,860.00 in unpaid tax.\n\nIf payment is not received today the matter will be passed to Police. Payment can be made with prepaid vouchers. Reply to this email with the voucher numbers.","link_text":"","link_url":"","is_phishing":true,"category":"Tax and government","difficulty":"medium","clues":["Threatens Police action if you do not pay today.","Asks for payment in prepaid vouchers, which cannot be traced or reversed.","Not from ird.govt.nz."],"explanation":"Netsafe lists 'pay now or face Police action' and gift or prepaid card payments as classic signs of an impersonation scam. There is no link here, which shows a phishing message does not need one.","source":"Modelled on a Netsafe warning about tax scams (June 2026)","source_url":"https://resource.netsafe.org.nz/Netsafe-Warns-of-Tax-Refund-Scam-Surge_media-release-June-4-2026.pdf"},{"channel":"email","sender":"NZTA Renewals <renewals@nzta-licence.co>","subject":"Vehicle registration expires in 2 days","body":"Your vehicle registration expires in 2 days.\n\nRenew now to avoid an infringement fine of $200. Have your card and driver licence details ready.","link_text":"Renew registration","link_url":"https://nzta-licence.co/renew","is_phishing":true,"category":"Tax and government","difficulty":"easy","clues":["The real NZTA domain is nzta.govt.nz, not nzta-licence.co.","Threatens a fine to rush you.","Asks for card and driver licence details."],"explanation":"NZTA renewal messages have been used as bait alongside Inland Revenue ones. The fake page collects card details and licence information, which is enough for identity theft.","source":"Modelled on ANZ's notice about IRD and NZTA scams","source_url":"https://anz.co.nz/banking-with-anz/banking-safely/recognise-scams-fraud/latest-scams/august-2022-IRD-and-NZTA-phishing-scams"},{"channel":"sms","sender":"+64 22 555 0188","subject":"","body":"NZ Post: Your package has arrived at our warehouse and delivery is on hold. Confirm your home phone number to book a new delivery.","link_text":"Book delivery","link_url":"https://nzpost-redelivery.com/confirm","is_phishing":true,"category":"Parcels and deliveries","difficulty":"easy","clues":["The link is nzpost-redelivery.com. NZ Post uses nzpost.co.nz.","Asks you to hand over personal details.","You may not be expecting a parcel at all."],"explanation":"NZ Post and Westpac have both warned about parcel-on-hold texts. The links lead to sites that collect personal details or put malware on a phone.","source":"Modelled on a Westpac and NZ Post scam warning","source_url":"https://www.newstalkzb.co.nz/news/business/nz-post-westpac-warn-of-text-message-phishing-scam-aimed-at-infecting-devices"},{"channel":"email","sender":"NZ Post <delivery@nzpost-parcels.info>","subject":"Redelivery fee due","body":"We tried to deliver your parcel today but nobody was home.\n\nA redelivery fee of $2.15 is due. Pay now or your parcel will be returned to the sender.","link_text":"Pay $2.15 now","link_url":"https://nzpost-parcels.info/pay","is_phishing":true,"category":"Parcels and deliveries","difficulty":"medium","clues":["The .info ending is on many spam lists.","A tiny fee makes you less careful about handing over a card.","The domain is not nzpost.co.nz."],"explanation":"The amount is small on purpose. The scammer wants your card number, expiry date and security code, and may use them for much larger charges later.","source":"Common pattern seen in parcel scam reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"DHL Express <noreply@dhl-customs-fee.com>","subject":"Your shipment is on hold: customs fee","body":"Your shipment 4482 9173 05 is on hold at customs.\n\nA clearance fee of $3.20 must be paid within 24 hours or the shipment will be returned.","link_text":"Pay customs fee","link_url":"https://dhl-customs-fee.com/pay","is_phishing":true,"category":"Parcels and deliveries","difficulty":"easy","clues":["The sender domain is dhl-customs-fee.com, not dhl.com.","A 24 hour limit.","A small fee is used to get your card details."],"explanation":"Real tracking numbers look just like this one, which is why parcel scams work. Check the number on the courier's own website instead of the link in the message.","source":"Common pattern seen in parcel scam reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"ANZ Security <security@anz-secure-login.co>","subject":"Your Internet Banking access has been restricted","body":"We detected a sign-in from a new device. For your protection your access has been restricted.\n\nLog in now to restore access.","link_text":"Restore access","link_url":"https://anz-secure-login.co/restore","is_phishing":true,"category":"Banking","difficulty":"easy","clues":["The domain is anz-secure-login.co. ANZ uses anz.co.nz.","Fear of a locked account.","The only way out is a login page behind a link."],"explanation":"The fake page looks like a bank login but sends your username and password to the scammer. Go to your bank by typing its address yourself.","source":"Modelled on ANZ's notice about banking scams","source_url":"https://anz.co.nz/banking-with-anz/banking-safely/recognise-scams-fraud/latest-scams/august-2022-IRD-and-NZTA-phishing-scams"},{"channel":"sms","sender":"Kiwibank","subject":"","body":"Kiwibank: Did you just try to make a payment of $1,249.00 to JMD Traders? If not, cancel it now and enter the code we send you.","link_text":"Cancel payment","link_url":"https://kiwibank-cancel.com/verify","is_phishing":true,"category":"Banking","difficulty":"hard","clues":["The sender shows only a name, and text sender names can be faked, so it can sit in the same thread as real bank texts.","The link is kiwibank-cancel.com, not kiwibank.co.nz.","It asks you to enter a code that you are sent. That code is the key to your account."],"explanation":"The scammer is logging in to your real account at the same moment and needs the code that arrives. Giving it over defeats two-factor protection. A bank will not ask you to type a code into a page from a text.","source":"Modelled on the 'enter the code' lure in Netsafe's tax scam warning","source_url":"https://resource.netsafe.org.nz/Netsafe-Warns-of-Tax-Refund-Scam-Surge_media-release-June-4-2026.pdf"},{"channel":"email","sender":"Westpac <alerts@westpac.co.nz>","subject":"Your statement is ready","body":"Kia ora,\n\nYour latest statement is ready to view. Log in to see your balance and recent transactions.","link_text":"westpac.co.nz/statements","link_url":"https://westpac-statements.cc/login","is_phishing":true,"category":"Banking","difficulty":"hard","clues":["The sender looks right, but sender addresses can be faked.","The text of the link says westpac.co.nz, but it goes to westpac-statements.cc.","Check where a link really goes before you click."],"explanation":"Link text can say anything. Hover over a link, or press and hold on a phone, to see where it goes. Here the sender and the visible text look right and only the real destination gives it away.","source":"Common pattern: display text that hides the real destination","source_url":""},{"channel":"email","sender":"Kiwibank Fraud Team <fraud@kiwibank-alerts.net>","subject":"New payee added to your account","body":"A new payee, J. Marlow, was added to your account from a new device.\n\nIf this was not you, review it immediately.","link_text":"Review payee","link_url":"https://kiwibank-alerts.net/review","is_phishing":true,"category":"Banking","difficulty":"medium","clues":["Not from kiwibank.co.nz.","Creates alarm about something you did not do.","The fix is a link, not 'log in the usual way'."],"explanation":"When the message makes you worry, you act before you check. A real alert gives you the facts and tells you to open your banking app yourself.","source":"Common pattern seen in bank phishing reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"Microsoft 365 <no-reply@micros0ft-support.com>","subject":"Action required: your password expires in 24 hours","body":"Your Microsoft 365 password expires today at 5:00 PM.\n\nTo keep your current password and avoid losing access to mail and files, confirm below.","link_text":"Keep my password","link_url":"https://micros0ft-support.com/keep","is_phishing":true,"category":"Online accounts","difficulty":"easy","clues":["micros0ft has a zero where the letter o should be.","A deadline of a few hours.","You never need to 'keep' a password through a link."],"explanation":"The zero in place of the letter o is a classic. Password-expiry notices are one of the most common lures against work accounts.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"IT Support <support@mail-quota-center.com>","subject":"Mailbox storage 98% full","body":"Dear user,\n\nYour mailbox has reached 98% of its quota. Verify your account immediately or incoming mail will be deleted.","link_text":"Verify account","link_url":"https://mail-quota-center.com/verify","is_phishing":true,"category":"Work","difficulty":"easy","clues":["'Dear user' instead of your name.","Your real IT team would not use a domain you have never heard of.","Threatens that mail will be deleted."],"explanation":"The generic greeting, the threat and the unknown domain all point the same way. If you doubt a message from IT, ask them in person or through a channel you already use.","source":"Common pattern seen in workplace phishing. Wording written for this quiz","source_url":""},{"channel":"email","sender":"Sarah Lin <sarah.lin.work88@gmail.com>","subject":"Q3 Financial Report shared with you","body":"Sarah Lin shared a document with you.\n\nQ3_Financial_Report.pdf\n\nOpen to view.","link_text":"Open in Docs","link_url":"https://docs-google-share.com/view/q3","is_phishing":true,"category":"Online accounts","difficulty":"medium","clues":["You do not know Sarah, or you were not expecting a report from her.","A personal Gmail address is sending a business document.","The link goes to docs-google-share.com, not docs.google.com."],"explanation":"The page behind the link is a copy of the Google login. Anything you type goes straight to the scammer. If you are unsure, ask the sender through another channel.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Apple Support <appleid@apple-id-billing.com>","subject":"Your Apple ID has been suspended","body":"We could not verify your payment method.\n\nUpdate it within 48 hours or your Apple ID and all its data will be permanently disabled.","link_text":"Update payment method","link_url":"https://apple-id-billing.com/update","is_phishing":true,"category":"Online accounts","difficulty":"easy","clues":["apple-id-billing.com is not an Apple domain.","A threat of permanent data loss.","Asks for payment details through a link."],"explanation":"Real account problems show up when you sign in to the account yourself. Threats of permanent loss are meant to stop you thinking.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Netflix <info@netf1ix-billing.com>","subject":"Your payment was declined","body":"We're having trouble with your current billing information.\n\nUpdate your payment details before 12 June or your membership will be cancelled.","link_text":"Update account now","link_url":"https://netf1ix-billing.com/account","is_phishing":true,"category":"Online accounts","difficulty":"medium","clues":["netf1ix uses the number 1 in place of the letter l.","A date to create pressure.","Asks you to retype payment details."],"explanation":"At a glance netf1ix and netflix look alike. Reading the domain slowly, one letter at a time, is a habit that catches many scams.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Instagram Support <no-reply@insta-copyright-team.com>","subject":"Copyright violation: appeal within 24 hours","body":"Your account has been reported for a copyright violation.\n\nSubmit an appeal within 24 hours or your account will be permanently disabled.","link_text":"Submit appeal","link_url":"https://insta-copyright-team.com/appeal","is_phishing":true,"category":"Social media","difficulty":"medium","clues":["Not an Instagram domain.","A 24 hour deadline.","The appeal form wants your password."],"explanation":"The goal is to take over the account so the scammer can message your followers. Appeals are made in the app's own settings, not through email forms.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Meta Security <security@facebook-secure-login.com>","subject":"Someone tried to log in to your account","body":"We noticed a login attempt from Lagos, Nigeria.\n\nIf this was not you, secure your account now.","link_text":"Secure my account","link_url":"https://facebook-secure-login.com/secure","is_phishing":true,"category":"Social media","difficulty":"easy","clues":["facebook-secure-login.com is not facebook.com.","A distant place makes the attempt feel real.","Security fixes happen in the app, not through emailed links."],"explanation":"The foreign location is there to scare you. Open the real app or site yourself and check the security settings.","source":"Common pattern seen in account takeover reports. Wording written for this quiz","source_url":""},{"channel":"social","sender":"Mia Thompson (Messenger)","subject":"","body":"omg is this you in this video?? 😳","link_text":"Watch video","link_url":"https://fb-video-watch.top/v/893021","is_phishing":true,"category":"Social media","difficulty":"medium","clues":["A friend's account that has been hacked can send this to everyone.","A vague message with a shock hook and nothing personal.","The link is not facebook.com."],"explanation":"The message is sent from a real friend's hacked account, so trust in the name is misplaced. If a friend sends a short message with just a link, check with them another way.","source":"Common pattern seen in account takeover reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"DocuSign <dse@docusign-secure.net>","subject":"Completed: Employment agreement for review","body":"Mark Hoskins sent you a document to review and sign.\n\nTo open it, sign in with your email password.","link_text":"Review document","link_url":"https://docusign-secure.net/review/8821","is_phishing":true,"category":"Work","difficulty":"hard","clues":["Asks you to sign in with your email password to open a document.","docusign-secure.net is not the company's own domain.","You are not expecting an employment agreement."],"explanation":"A real document service does not need your email password to show you a file. The fake page collects it so the scammer can read your mail.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Rachel Tan <rachel.tan.ceo@outlook.com>","subject":"Quick favour","body":"Are you at your desk? I'm in a meeting and cannot talk.\n\nI need you to buy 5 x $100 gift cards for clients today. I will reimburse you. Please keep this between us and send me the codes when you have them.","link_text":"","link_url":"","is_phishing":true,"category":"Work","difficulty":"medium","clues":["A senior person using a personal Outlook address.","Asks you to keep it secret.","Gift card codes are the same as cash."],"explanation":"This is the 'boss needs a favour' scam. Secrecy and urgency stop you from checking. Walk over or call the person on a number you already have.","source":"Pattern from a published catalogue of phishing emails (executive impersonation)","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Accounts <accounts@brightline-suppliers.co.nz>","subject":"Updated bank details for Invoice 4471","body":"Hi,\n\nOur bank details have changed. Please pay the outstanding invoice to the new account below and use it for all future payments.\n\nNew account: 12-3456-0789012-00\n\nWe are sending from a new address while our email is moved.","link_text":"","link_url":"","is_phishing":true,"category":"Work","difficulty":"hard","clues":["Your usual supplier is brightline-supplies.co.nz. This is brightline-suppliers.co.nz.","Bank details have changed with no phone call.","The odd email address is explained away."],"explanation":"This is invoice redirection. One letter in the domain differs and the explanation sounds sensible. Always confirm new bank details by phoning a number you already hold.","source":"Common pattern seen in business email compromise. Wording written for this quiz","source_url":""},{"channel":"email","sender":"HR Team <hr@company-benefits-portal.org>","subject":"Open enrolment: action required before midnight Friday","body":"Open enrolment for 2026 closes at midnight on Friday.\n\nSign in to the benefits portal with your work login to review your options. Anyone who does not respond will lose cover.","link_text":"Sign in to benefits portal","link_url":"https://company-benefits-portal.org/login","is_phishing":true,"category":"Work","difficulty":"medium","clues":["A portal on a domain your employer does not own.","A cliff-edge deadline with loss of cover.","Asks for your work login."],"explanation":"Attackers often copy details from LinkedIn to make an HR message look real. Check internal notices on your intranet or ask HR directly.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Voice Message <vm@voicemail-notify.net>","subject":"New voicemail from +64 9 555 0134","body":"You have 1 new voicemail (0:42).\n\nListen to the message using the link below.","link_text":"Listen to voicemail","link_url":"https://voicemail-notify.net/play/listen.html","is_phishing":true,"category":"Online accounts","difficulty":"medium","clues":["A voicemail that opens a web page, not an audio player.","The address ends in .html, a web file that can show a fake login.","Curiosity is the bait."],"explanation":"The page opens a fake Microsoft login. The voicemail never existed.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Zoom <no-reply@zoom-meetings-invite.com>","subject":"Quarterly performance review: join meeting","body":"You have been invited to a Zoom meeting.\n\nTopic: Quarterly performance review\nTo join, install the latest Zoom update first.","link_text":"Join meeting","link_url":"https://zoom-meetings-invite.com/download","is_phishing":true,"category":"Work","difficulty":"hard","clues":["The domain is zoom-meetings-invite.com. The real one is zoom.us.","A meeting that needs you to install something first.","The topic plays on worry about a review."],"explanation":"The 'update' is malware. A real meeting link opens the meeting. Install updates only from the app itself or the official website.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Amazon Orders <orders@amazon-order-confirm.com>","subject":"Order confirmed: MacBook Pro $2,899.00","body":"Thanks for your order.\n\n1 x MacBook Pro 14-inch, $2,899.00\n\nIf you did not place this order, cancel it here and request a refund.","link_text":"Cancel order","link_url":"https://amazon-order-confirm.com/cancel","is_phishing":true,"category":"Shopping","difficulty":"medium","clues":["An order you never made.","amazon-order-confirm.com is not amazon.com.","The 'cancel' page asks you to sign in."],"explanation":"A big charge is meant to trigger panic. Check your orders by opening the Amazon app or website yourself.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Trade Me <support@trademe-payouts.net>","subject":"Payment on hold for your sold item","body":"Your item sold for $780.00 but the payment is on hold.\n\nVerify your bank details to release the funds within 24 hours.","link_text":"Release payment","link_url":"https://trademe-payouts.net/verify","is_phishing":true,"category":"Shopping","difficulty":"medium","clues":["trademe-payouts.net is not trademe.co.nz.","Money waiting for you is bait.","Asks you to give bank details through a link."],"explanation":"Sellers on marketplaces are targeted because they expect payments. Check the sale from your own account.","source":"Common pattern seen in marketplace scam reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"McAfee Billing <billing@protect-renewals.com>","subject":"Your subscription has renewed: $549.00","body":"Thank you. Your annual subscription has renewed for $549.00.\n\nIf you did not authorise this charge, call us immediately on 0800 555 019 for a full refund.","link_text":"","link_url":"","is_phishing":true,"category":"Shopping","difficulty":"hard","clues":["No link at all, but a phone number to call.","A large charge you did not agree to.","The sender domain is not the company's."],"explanation":"This is callback phishing. The person who answers asks to 'fix' the refund by taking control of your computer or collecting your banking details. The phone number is the trap.","source":"Common pattern known as callback phishing. Wording written for this quiz","source_url":""}]$q$::jsonb) as t(channel text,sender text,subject text,body text,link_text text,link_url text,is_phishing boolean,category text,difficulty text,clues text[],explanation text,source text,source_url text);
insert into quiz_examples (channel,sender,subject,body,link_text,link_url,is_phishing,category,difficulty,clues,explanation,source,source_url) select channel,sender,subject,body,link_text,link_url,is_phishing,category,difficulty,clues,explanation,source,source_url from jsonb_to_recordset($q$[{"channel":"email","sender":"Mercury Billing <billing@mercury-energy-nz.com>","subject":"Disconnection notice","body":"Your account is overdue by $187.40.\n\nYour power will be disconnected in 2 hours unless payment is made now.","link_text":"Pay now","link_url":"https://mercury-energy-nz.com/pay","is_phishing":true,"category":"Shopping","difficulty":"easy","clues":["A two hour disconnection threat.","A look-alike company domain.","A link to pay by card."],"explanation":"Real power companies send reminders and give time. A few hours is an invention to stop you from checking.","source":"Common pattern seen in utility scam reports. Wording written for this quiz","source_url":""},{"channel":"sms","sender":"+64 27 555 0129","subject":"","body":"Spark: You have unclaimed rewards points worth $250 that expire tomorrow. Redeem now.","link_text":"Redeem points","link_url":"https://spark-rewards-nz.xyz/redeem","is_phishing":true,"category":"Crypto and prizes","difficulty":"easy","clues":["Free money that expires tomorrow.","A .xyz link.","Sent from a regular mobile number."],"explanation":"Rewards that disappear tomorrow are a lure. The page asks for card details to 'verify' you.","source":"Common pattern seen in text scam reports. Wording written for this quiz","source_url":""},{"channel":"sms","sender":"+64 20 555 0176","subject":"","body":"Unpaid toll: you owe $4.80. Pay today to avoid a $60 late fee.","link_text":"Pay toll","link_url":"https://nz-toll-payments.top/pay","is_phishing":true,"category":"Tax and government","difficulty":"medium","clues":["A small amount, with a large late fee if you wait.","A cheap .top domain.","A text from a mobile number with no account details."],"explanation":"A real toll notice would name the road and your plate. Small debts catch people because paying seems easier than checking.","source":"Common pattern seen in text scam reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"OpenSea Rewards <rewards@opensea-airdrop.xyz>","subject":"You have received 0.75 ETH","body":"Congratulations! You have received 0.75 ETH in our community airdrop.\n\nConnect your wallet to claim before it expires.","link_text":"Claim ETH","link_url":"https://opensea-airdrop.xyz/claim","is_phishing":true,"category":"Crypto and prizes","difficulty":"medium","clues":["Free crypto from an unknown sender.","A .xyz domain.","Connecting a wallet can let a script empty it."],"explanation":"Connecting your wallet to a fake site can hand over permission to move your funds. Nobody gives away crypto by email.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Ledger Support <security@ledger-recovery.com>","subject":"Verify your recovery phrase","body":"Due to a firmware issue we need you to validate your 24 word recovery phrase within 24 hours.\n\nEnter it on the secure page below to keep your funds protected.","link_text":"Validate recovery phrase","link_url":"https://ledger-recovery.com/validate","is_phishing":true,"category":"Crypto and prizes","difficulty":"easy","clues":["Nobody legitimate will ever ask for your recovery phrase.","A 24 hour deadline.","The domain is not ledger.com."],"explanation":"A recovery phrase is the master key to a wallet. Whoever has it can take everything, and the transfer cannot be reversed.","source":"Common pattern: wallet brands were among the most imitated in live phishing feeds checked for this project","source_url":""},{"channel":"email","sender":"Winner Notification <claims@prize-center.club>","subject":"You've won a $500 voucher","body":"Congratulations! You have been selected as a winner of a $500 supermarket voucher.\n\nClaim your prize now. This offer expires today.","link_text":"Claim prize","link_url":"https://prize-center.club/claim","is_phishing":true,"category":"Crypto and prizes","difficulty":"easy","clues":["You did not enter a draw.","'Expires today' pressure.","A .club domain."],"explanation":"If you did not enter, you cannot have won. These pages collect an address, phone number and card details for 'delivery'.","source":"Common pattern seen in prize scam reports. Wording written for this quiz","source_url":""},{"channel":"email","sender":"Global Talent Team <recruiting@careers-global-hire.com>","subject":"Remote role, $195k: we reviewed your profile","body":"Hi,\n\nWe reviewed your LinkedIn profile and think you are a strong match for a remote role paying $195,000.\n\nApply using the form below. You will be asked for your IRD number and a copy of your driver licence to start onboarding.","link_text":"Apply here","link_url":"https://careers-global-hire.com/apply","is_phishing":true,"category":"Work","difficulty":"medium","clues":["An unsolicited offer with a very high salary.","Asks for your IRD number and licence before an interview.","No company named."],"explanation":"Fake job offers collect the details needed for identity theft. A real employer interviews you first and asks for ID only after hiring you.","source":"Pattern from a published catalogue of phishing emails","source_url":"https://isthisascam.to/blog/phishing-email-examples-2026"},{"channel":"email","sender":"Alex Morgan <alex.morgan@orbitdesign.co.nz>","subject":"Rosters updated, please confirm","body":"Hi team,\n\nI've updated the roster for next month. Can you open it and sign in with your work account to confirm your shifts? Need everyone done by 3pm.","link_text":"Open roster","link_url":"https://orbitdesign-rosters.co/confirm","is_phishing":true,"category":"Work","difficulty":"hard","clues":["It comes from a colleague, but a hacked account can send this.","The link goes to orbitdesign-rosters.co, not orbitdesign.co.nz.","Asks you to sign in to see a roster."],"explanation":"This is the dangerous kind: a real colleague's account taken over. The only giveaway is the link. Ask the person in person or on chat before you sign in anywhere.","source":"Common pattern seen in workplace phishing. Wording written for this quiz","source_url":""},{"channel":"email","sender":"noreply@github.com","subject":"A new SSH key was added to your account","body":"Hi Cameron,\n\nA new SSH key was added to your account. If this wasn't you, you can remove it in your account settings.\n\nKey fingerprint: SHA256:uNiVztksCsDhcc0u9e8BujQXVUpKZIDTMczCvj3tD2s","link_text":"Review SSH keys","link_url":"https://github.com/settings/keys","is_phishing":false,"category":"Online accounts","difficulty":"easy","clues":["The sender is exactly github.com.","The link goes to github.com.","It tells you what happened and asks for nothing."],"explanation":"A notice about a change you can check. It uses your name, gives a detail you can verify and sends you to the real domain.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Google <no-reply@accounts.google.com>","subject":"Security alert: new sign-in on Windows","body":"Your Google Account was just signed in to from a new Windows device.\n\nIf this was you, you don't need to do anything. If not, check your activity.","link_text":"Check activity","link_url":"https://myaccount.google.com/notifications","is_phishing":false,"category":"Online accounts","difficulty":"medium","clues":["accounts.google.com is part of google.com.","The link goes to myaccount.google.com.","It does not ask for your password or threaten you."],"explanation":"It looks like a scare, but nothing here asks for secrets. The sender and link are both real Google addresses, and 'no action needed' is an option.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Amazon <shipment-tracking@amazon.com>","subject":"Your package has shipped","body":"Your order of USB-C cable (2-pack) has shipped and should arrive Thursday.","link_text":"Track package","link_url":"https://www.amazon.com/progress-tracker/package","is_phishing":false,"category":"Shopping","difficulty":"easy","clues":["The sender and link are both amazon.com.","You placed this order.","It only gives you status."],"explanation":"A shipping update you were expecting, from the right domain, asking for nothing.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Spotify <no-reply@spotify.com>","subject":"Your receipt from Spotify","body":"Thanks for being on Premium.\n\nPremium Individual, 1 month: $15.99\nPaid with the card ending 4821.\n\nYour next payment is due in 30 days.","link_text":"","link_url":"","is_phishing":false,"category":"Shopping","difficulty":"easy","clues":["It is a receipt for something you already pay for.","There is no link and no request.","The sender is spotify.com."],"explanation":"A receipt asks you to do nothing. The last four digits of your own card are a detail only your provider would normally know.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Inland Revenue <noreply@ird.govt.nz>","subject":"You have a new message in myIR","body":"Kia ora,\n\nYou have a new secure message waiting.\n\nTo read it, log in to myIR from the Inland Revenue website.","link_text":"","link_url":"","is_phishing":false,"category":"Tax and government","difficulty":"hard","clues":["It comes from ird.govt.nz.","It has no link. It tells you to go to the website yourself.","It asks for no details and gives no amount or deadline."],"explanation":"Compare this with the fake IRD messages earlier. Inland Revenue says it does not put links in emails and that you should log in to myIR from its website. This message does exactly that.","source":"Based on Inland Revenue's published advice on genuine emails","source_url":"https://www.ird.govt.nz/managing-my-tax/scams/latest-scams"},{"channel":"sms","sender":"NZ Post","subject":"","body":"NZ Post: Your parcel is on its way and should be delivered tomorrow. Track it at the link below.","link_text":"Track parcel","link_url":"https://www.nzpost.co.nz/tools/tracking?trackid=NP1234567","is_phishing":false,"category":"Parcels and deliveries","difficulty":"medium","clues":["The link is nzpost.co.nz exactly.","It tells you the status and asks for no payment or details.","You were expecting a parcel."],"explanation":"The difference from the fake NZ Post texts is what it asks. This only gives a status and links to the real domain. If you are not expecting a parcel, treat it as suspect and go to the NZ Post site yourself.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"sms","sender":"ANZ","subject":"","body":"ANZ: A payment of $45.00 was made on your card ending 4821 at PAK'nSAVE. No action is needed.","link_text":"","link_url":"","is_phishing":false,"category":"Banking","difficulty":"medium","clues":["No link.","No request for a code or details.","'No action is needed' is the opposite of pressure."],"explanation":"A purchase alert you can check against your own card. Alerts like this ask for nothing, so there is nothing to give away.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Kiwibank <noreply@kiwibank.co.nz>","subject":"Your new statement is ready","body":"Kia ora Cameron,\n\nYour latest statement is ready. Log in to Internet Banking to view it.","link_text":"","link_url":"","is_phishing":false,"category":"Banking","difficulty":"medium","clues":["The sender is exactly kiwibank.co.nz.","No link, just 'log in' the way you normally do.","No deadline, no threat."],"explanation":"Compare this with the fake Westpac statement email. The safe habit is the same either way: go to your bank by your own bookmark or app.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Priya Nair <priya.nair@orbitdesign.co.nz>","subject":"Invitation: Design review Thursday 2pm","body":"Hi team,\n\nI've set up Thursday's design review for 2pm. Room 3 if you're in the office, link below if you're remote.","link_text":"Join meeting","link_url":"https://meet.google.com/abc-defg-hij","is_phishing":false,"category":"Work","difficulty":"medium","clues":["Your own company's domain.","The meeting is normal and expected.","It goes to meet.google.com and asks you to sign in to nothing."],"explanation":"A normal calendar invite. The link opens a real Google Meet room and the message asks for no password.","source":"Typical legitimate message. Written for this quiz","source_url":""},{"channel":"email","sender":"LinkedIn <invitations@linkedin.com>","subject":"Jordan Wu wants to connect","body":"Jordan Wu, Software Engineer at Kauri Labs, would like to connect with you on LinkedIn.","link_text":"View invitation","link_url":"https://www.linkedin.com/comm/mynetwork/","is_phishing":false,"category":"Social media","difficulty":"medium","clues":["Sent from linkedin.com and links to linkedin.com.","It does not threaten you or ask for anything.","You can check by opening LinkedIn yourself."],"explanation":"A normal connection request. If you are unsure about it, skip the email and look in the LinkedIn app.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Trade Me <noreply@trademe.co.nz>","subject":"Your item sold","body":"Your listing 'Vintage desk lamp' sold for $65.00.\n\nContact the buyer through your Trade Me account to arrange payment and pickup.","link_text":"View in My Trade Me","link_url":"https://www.trademe.co.nz/","is_phishing":false,"category":"Shopping","difficulty":"hard","clues":["Sender and link are both trademe.co.nz.","It names a listing you made.","It does not ask for bank details or put the money 'on hold'."],"explanation":"Compare it with the fake Trade Me message earlier. The real one only tells you about the sale and sends you to your own account.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Dropbox <no-reply@dropbox.com>","subject":"Reset your Dropbox password","body":"Someone asked to reset the password for your account.\n\nThis link expires in 24 hours. If you didn't ask for this, you can ignore this email and your password will stay the same.","link_text":"Reset password","link_url":"https://www.dropbox.com/forgot_finish?token=abc123","is_phishing":false,"category":"Online accounts","difficulty":"hard","clues":["You asked for the reset a moment ago.","The link is dropbox.com.","'Ignore this' is an option, so nothing bad happens if you do nothing."],"explanation":"A time limit on its own is not a red flag. Here you triggered it, the link is genuine, and doing nothing costs you nothing. Compare that with threats that your account will be lost.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Kiwi Coast Ferries <bookings@mail.kiwicoastferries.co.nz>","subject":"Check-in is open for your Thursday crossing","body":"Kia ora Cameron,\n\nOnline check-in for your Thursday 8:30am sailing is now open. Have your booking reference ready: KCF-48201.","link_text":"Check in","link_url":"https://www.kiwicoastferries.co.nz/check-in","is_phishing":false,"category":"Parcels and deliveries","difficulty":"hard","clues":["The sender is a subdomain (mail.) of the company's own site.","The link goes to the same company domain.","It refers to a booking you made."],"explanation":"Companies often send mail from a subdomain such as mail or email. What matters is the part just before the last dot and ending, here kiwicoastferries.co.nz. It matches the link and your booking.","source":"Typical legitimate message. Written for this quiz","source_url":""},{"channel":"email","sender":"Sam Carter <sam.carter@orbitdesign.co.nz>","subject":"Friday drinks","body":"Hey team,\n\nFriday drinks at 4pm in the kitchen. Bring a plate if you can.","link_text":"","link_url":"","is_phishing":false,"category":"Work","difficulty":"easy","clues":["Your own company's address.","Nothing to click and nothing to hand over.","Fits what you expect from this person."],"explanation":"Plenty of messages are just messages. A message that asks for nothing is rarely phishing.","source":"Typical legitimate message. Written for this quiz","source_url":""},{"channel":"email","sender":"Student Services <studentservices@kauri-polytech.ac.nz>","subject":"Library book due Monday","body":"Kia ora,\n\nYour library book 'Computer Networks' is due back on Monday. You can renew it online from the library website.","link_text":"","link_url":"","is_phishing":false,"category":"Work","difficulty":"easy","clues":["A familiar sender that you deal with.","No link, just a pointer to the website you already use.","A small, plausible request."],"explanation":"A routine reminder that tells you to go to the website yourself, which is the safe way to do it.","source":"Typical legitimate message. Written for this quiz","source_url":""},{"channel":"email","sender":"Mighty Ape <orders@mightyape.co.nz>","subject":"Order MA-88213 confirmed","body":"Thanks for your order.\n\n1 x Board game, $59.99\nDelivery to the address on your account in 3 to 5 working days.","link_text":"View order","link_url":"https://www.mightyape.co.nz/account/orders","is_phishing":false,"category":"Shopping","difficulty":"medium","clues":["You placed this order.","The sender and link both use mightyape.co.nz.","It does not ask you to pay or sign in."],"explanation":"An order confirmation for a purchase you remember. If you do not remember it, open your account directly instead of using the link.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"email","sender":"Netflix <info@mailer.netflix.com>","subject":"New device signed in to your account","body":"A new device just signed in to your Netflix account.\n\nIf this was you, there's nothing to do. If not, go to netflix.com and change your password.","link_text":"","link_url":"","is_phishing":false,"category":"Online accounts","difficulty":"hard","clues":["mailer.netflix.com is a subdomain of netflix.com.","It tells you to go to netflix.com yourself instead of giving a link.","No payment request."],"explanation":"This looks odd because of the 'mailer' part, but the domain that counts is netflix.com. Being told to go to the site yourself is a good sign.","source":"Typical legitimate notification. Written for this quiz","source_url":""},{"channel":"sms","sender":"Harbour Medical","subject":"","body":"Harbour Medical: Reminder of your appointment with Dr Lee tomorrow at 10:20am. Reply C to confirm or call 07 555 0123 to change.","link_text":"","link_url":"","is_phishing":false,"category":"Online accounts","difficulty":"easy","clues":["A real appointment that you made.","No link.","The phone number is one you can match to the clinic's website."],"explanation":"Appointment reminders are routine. A simple reply or a call to a number you can check is a low-risk request.","source":"Typical legitimate message. Written for this quiz","source_url":""},{"channel":"sms","sender":"Google","subject":"","body":"G-482913 is your Google verification code.","link_text":"","link_url":"","is_phishing":false,"category":"Online accounts","difficulty":"hard","clues":["You just tried to sign in, so you expected it.","It has no link and no request.","The only rule is that you keep the code to yourself."],"explanation":"A code you asked for is safe as long as you do not pass it on. Compare this with the fake bank text that asked you to type a code into a web page.","source":"Typical legitimate message. Written for this quiz","source_url":""},{"channel":"email","sender":"Uber Receipts <noreply@uber.com>","subject":"Your Friday evening trip with Uber","body":"Thanks for riding, Cameron.\n\nTotal: $18.40\nPaid with the card ending 4821.\n\nHow was your trip?","link_text":"","link_url":"","is_phishing":false,"category":"Shopping","difficulty":"easy","clues":["A trip you remember taking.","Sent from uber.com.","It asks only how the trip was."],"explanation":"A receipt for something you did. If you did not take the trip, do not use the links. Open the app and check your trips.","source":"Typical legitimate notification. Written for this quiz","source_url":""}]$q$::jsonb) as t(channel text,sender text,subject text,body text,link_text text,link_url text,is_phishing boolean,category text,difficulty text,clues text[],explanation text,source text,source_url text);
